from pydantic import BaseModel

class LLMErrorEnvelope(BaseModel):
    error_type: str  # rate_limit, auth, overloaded, context_overflow, 4xx_client, network, etc.
    status_code: int | None
    actionable: str  # human-readable sentence the LLM can act on

class ErrorClassifier:
    _NO_ACCESS = ('model_not_found', 'does not exist or you do not have access', 'permission_error')
    _NO_QUOTA = ('insufficient_quota', 'credit balance is too low', 'exceeded your current quota')

    @classmethod
    def classify(cls, exc: Exception) -> LLMErrorEnvelope:
        text = str(exc).lower()
        for marker in cls._NO_QUOTA:
            if marker in text:
                return LLMErrorEnvelope(error_type='quota', status_code=None, actionable='Your account is out of quota — add credits or pick a different model.')
        return LLMErrorEnvelope(error_type='other', status_code=None, actionable=str(exc))

# Surface as ToolError so it's visible in conversation
try:
    result = provider.complete(model=model, messages=messages)
except Exception as exc:
    envelope = ErrorClassifier.classify(exc)
    raise ToolError(envelope.model_dump_json())
